DO $rv035_outer$ BEGIN EXECUTE $rv035_stmt$create or replace function public.rv_tx_action(p_deal uuid,p_action text,p_date date default null,p_document uuid default null,p_note text default '') returns void language plpgsql security definer set search_path='' as $$ declare d public.deal_files; doc public.deal_documents; agent boolean; office boolean; today date:=(now() at time zone 'America/Vancouver')::date; v_requirement_label text; begin select * into d from public.deal_files where id=p_deal for update; if not found or d.brokerage_id is distinct from public.current_brokerage() or auth.uid() is null then raise exception 'File unavailable';end if; agent:=d.user_id=auth.uid();office:=public.can_review_deal(d.user_id);if not (agent or office) then raise exception 'File unavailable';end if; if p_document is not null then select * into doc from public.deal_documents where id=p_document and deal_id=d.id;if not found or lower(doc.name) not like '%.pdf' or not exists(select 1 from storage.objects o where o.bucket_id='transaction-files' and o.name=doc.path) then raise exception 'Select an uploaded PDF from this transaction';end if;end if; perform set_config('realvolt.lifecycle_rpc','yes',true); if p_action='seen' and office and d.review_status='Submitted' then if not exists(select 1 from public.rv_transaction_notifications n where n.deal_id=d.id and n.recipient_id=d.user_id and n.message='Back Office opened your file' and n.created_at>=d.updated_at) then perform public.rv_tx_notice(d,'agent','Back Office opened your file');end if; elsif p_action='reopen' and agent and d.kind='Sale' and d.review_status='Approved' and (d.rv_stage is null or d.rv_stage='Accepted offer') then update public.deal_files set review_status='Changes requested' where id=d.id; elsif p_action='firm' and agent and d.kind='Sale' and d.review_status in ('Draft','Changes requested','Approved') and (d.rv_stage is null or d.rv_stage='Accepted offer') then if p_document is null or p_date is null or p_date>today or d.contract_date is null or p_date<d.contract_date or d.completion_date is null or d.completion_date<p_date or d.sale_price is null or d.sale_price<=0 or btrim(d.buyer_name)='' or btrim(d.seller_name)='' or d.buyer_lawyer_id is null or d.seller_lawyer_id is null then raise exception 'Enter contract/completion dates, buyer and seller, price, both lawyers and signed subject removal (or unconditional contract) PDF';end if; if not exists(select 1 from public.transaction_reviewers r join public.brokerage_members m on m.user_id=r.admin_id and m.brokerage_id=d.brokerage_id and m.role='admin' where r.agent_id=d.user_id) then raise exception 'No assigned reviewer';end if; insert into public.deal_requirements(deal_id,label,document_id,verified) values(d.id,'Signed subject removal / unconditional contract',p_document,false) on conflict(deal_id,label) do update set document_id=excluded.document_id,verified=false; update public.deal_files set rv_stage='Sold',rv_firm_date=p_date,review_status='Submitted' where id=d.id; perform public.rv_tx_notice(d,'office','Firm sale submitted — verify subject removal'); elsif p_action in ('extend_subject','extend_completion','collapse') and agent and d.kind='Sale' and d.review_status='Approved' and (d.rv_stage='Accepted offer' or (d.rv_stage='Sold' and p_action='extend_completion')) then if p_document is null or (p_action<>'collapse' and p_date is null) then raise exception 'Upload and select the signed amendment PDF and revised date';end if; if p_action='extend_subject' and (d.rv_stage<>'Accepted offer' or p_date<=coalesce(d.subject_date,d.contract_date) or (d.completion_date is not null and p_date>d.completion_date)) then raise exception 'Enter a later subject date before completion';end if; if p_action='extend_completion' and p_date<=coalesce(d.completion_date,d.contract_date) then raise exception 'Enter a later completion date';end if; v_requirement_label:=case p_action when 'extend_subject' then 'Subject extension' when 'extend_completion' then 'Completion extension' else 'Offer collapse' end||' — '||p_document::text; insert into public.deal_requirements(deal_id,label,document_id) values(d.id,v_requirement_label,p_document) on conflict do nothing; update public.deal_files set subject_date=case when p_action='extend_subject' then p_date else subject_date end,completion_date=case when p_action='extend_completion' then p_date else completion_date end,rv_stage=case when p_action='collapse' then 'Collapsed' else rv_stage end,review_status='Submitted' where id=d.id; elsif p_action in ('terminate','extend_listing') and agent and d.kind='Listing' and d.review_status='Approved' then if p_document is null or p_date is null or (p_action='terminate' and (btrim(p_note)='' or p_date>today)) then raise exception 'Select signed PDF, date and termination reason where applicable';end if; if exists(select 1 from public.deal_files s where s.parent_listing_id=d.id and s.rv_stage is distinct from 'Collapsed') then raise exception 'Resolve linked sale before amending listing';end if; if p_action='extend_listing' and (p_date<=today or exists(select 1 from public.listing_terms t where t.deal_id=d.id and (t.termination_date is not null or t.expiry_date>=p_date))) then raise exception 'Choose a later expiry date for an unterminated listing';end if; insert into public.deal_requirements(deal_id,label,document_id) values(d.id,(case when p_action='terminate' then 'Termination' else 'Listing extension' end)||' — '||p_document::text,p_document) on conflict do nothing; if p_action='terminate' then update public.listing_terms set termination_date=p_date,termination_reason=p_note where deal_id=d.id;else update public.listing_terms set expiry_date=p_date where deal_id=d.id;end if; update public.deal_files set review_status='Submitted' where id=d.id; elsif p_action='complete' and office and d.rv_stage='Sold' and d.review_status='Approved' then if p_document is null or p_date is null or p_date>today or p_date<d.rv_firm_date then raise exception 'Select lawyer completion letter PDF and actual completion date';end if; update public.deal_files set rv_stage='Completed',rv_completed_date=p_date,rv_completion_letter=p_document where id=d.id; perform public.rv_tx_notice(d,'agent','Legal completion confirmed'); elsif p_action='funds' and office and d.rv_stage='Completed' then if btrim(p_note)='' then raise exception 'Record verified receipt / bank reference';end if; update public.deal_files set rv_funds_verified=true where id=d.id; insert into public.transaction_audit_events(deal_id,actor_id,action,new_values) values(d.id,auth.uid(),'Commission funds verified',jsonb_build_object('reference',p_note)); elsif p_action='missing' and office and d.review_status in ('Submitted','Approved') then if btrim(p_note)='' then raise exception 'Enter missing documents';end if;perform public.rv_tx_notice(d,'agent','Documents required: '||p_note); elsif p_action='archive' and office and d.rv_stage='Completed' then if not exists(select 1 from public.agent_payouts where deal_id=d.id and status='Paid') or exists(select 1 from public.deal_requirements where deal_id=d.id and not verified) then raise exception 'Verify final documents and record agent payment first';end if; update public.deal_files set rv_stage='Archived' where id=d.id; else raise exception 'Action is not available for this file or role';end if; perform set_config('realvolt.lifecycle_rpc','no',true); end $$$rv035_stmt$; EXECUTE $rv035_stmt$create table if not exists public.rv_removed_deal_documents ( id uuid primary key, deal_id uuid not null references public.deal_files(id), name text not null, path text not null unique, created_at timestamptz not null, removed_by uuid not null references auth.users(id), removed_at timestamptz not null default now() )$rv035_stmt$; EXECUTE $rv035_stmt$alter table public.rv_removed_deal_documents enable row level security$rv035_stmt$; EXECUTE $rv035_stmt$revoke all on public.rv_removed_deal_documents from public, anon, authenticated$rv035_stmt$; EXECUTE $rv035_stmt$grant select on public.rv_removed_deal_documents to authenticated$rv035_stmt$; EXECUTE $rv035_stmt$drop policy if exists rv_removed_doc_review on public.rv_removed_deal_documents$rv035_stmt$; EXECUTE $rv035_stmt$create policy rv_removed_doc_review on public.rv_removed_deal_documents for select to authenticated using (exists(select 1 from public.deal_files d where d.id=deal_id and d.brokerage_id=public.current_brokerage() and public.can_review_deal(d.user_id) and d.review_status<>'Draft'))$rv035_stmt$; EXECUTE $rv035_stmt$drop policy if exists rv_removed_doc_download on storage.objects$rv035_stmt$; EXECUTE $rv035_stmt$create policy rv_removed_doc_download on storage.objects for select to authenticated using (bucket_id='transaction-files' and exists(select 1 from public.rv_removed_deal_documents x where x.path=storage.objects.name))$rv035_stmt$; EXECUTE $rv035_stmt$create or replace function public.rv_no_removed_doc_restore() returns trigger language plpgsql security definer set search_path='' as $$ begin if exists(select 1 from public.rv_removed_deal_documents x where x.id=new.id or x.path=new.path) then raise exception 'Removed file cannot be reattached; upload a new copy'; end if; return new; end $$$rv035_stmt$; EXECUTE $rv035_stmt$drop trigger if exists rv_no_removed_doc_restore on public.deal_documents$rv035_stmt$; EXECUTE $rv035_stmt$create trigger rv_no_removed_doc_restore before insert on public.deal_documents for each row execute function public.rv_no_removed_doc_restore()$rv035_stmt$; EXECUTE $rv035_stmt$create or replace function public.rv_remove_deal_document(p_deal uuid,p_document uuid) returns void language plpgsql security definer set search_path='' as $$ declare d public.deal_files; f public.deal_documents; v_agent boolean; v_office boolean; begin select * into d from public.deal_files where id=p_deal for update; if not found or auth.uid() is null or d.brokerage_id is null or d.brokerage_id is distinct from public.current_brokerage() then raise exception 'File unavailable'; end if; v_agent:=d.user_id=auth.uid(); v_office:=public.can_review_deal(d.user_id) and d.review_status<>'Draft'; if not (v_agent or v_office) then raise exception 'File unavailable'; end if; if d.rv_stage in ('Archived','Collapsed') or (d.kind='Listing' and exists(select 1 from public.rv_tx_summary s where s.id=d.id and s.display_status in ('Expired','Terminated','Sold'))) then raise exception 'Archived files are locked'; end if; select * into f from public.deal_documents where id=p_document and deal_id=d.id for update; if not found then raise exception 'Attachment unavailable'; end if; if v_agent and not v_office and split_part(f.path,'/',1)<>auth.uid()::text then raise exception 'Only Back Office can remove office-uploaded attachments'; end if; if d.rv_completion_letter=p_document then raise exception 'The legal completion letter is protected; contact Back Office'; end if; if exists(select 1 from public.deal_requirements r where r.document_id=f.id and r.deal_id<>d.id) then raise exception 'Attachment has another reference; contact Back Office'; end if; if exists(select 1 from public.deal_requirements r where r.document_id=f.id and r.label not in ('Signed listing contract','Signed purchase and sale contract')) then raise exception 'This document is linked to a required or signed lifecycle record. Ask Back Office to review the correction'; end if; if exists(select 1 from public.closing_deliveries c where c.deal_id=d.id and c.status in ('pending','accepted')) then raise exception 'Conveyancing history exists; contact Back Office before removing attachments'; end if; if exists(select 1 from public.deal_requirements r where r.document_id=f.id) then if not (d.review_status in ('Draft','Changes requested') or (v_office and d.review_status='Submitted')) or d.rv_stage in ('Sold','Completed','Archived') then raise exception 'This document is linked to a reviewed checklist. Back Office must handle the correction'; end if; update public.deal_requirements set document_id=null,verified=false where deal_id=d.id and document_id=f.id; end if; insert into public.rv_removed_deal_documents(id,deal_id,name,path,created_at,removed_by) values(f.id,f.deal_id,f.name,f.path,f.created_at,auth.uid()); insert into public.transaction_audit_events(deal_id,actor_id,action,record_id,old_values,new_values) values(d.id,auth.uid(),'Attachment removed from active file',f.id::text,to_jsonb(f),jsonb_build_object('retained',true)); delete from public.deal_documents where id=f.id and deal_id=d.id; if d.review_status='Submitted' then perform public.rv_tx_notice(d,case when v_office then 'agent' else 'office' end,'Attachment removed; review current documents'); end if; end $$$rv035_stmt$; EXECUTE $rv035_stmt$revoke all on function public.rv_remove_deal_document(uuid,uuid) from public,anon$rv035_stmt$; EXECUTE $rv035_stmt$grant execute on function public.rv_remove_deal_document(uuid,uuid) to authenticated$rv035_stmt$; END; $rv035_outer$;
